From f26ad64e8b178e5bcbd4611aee2af476ca0f4e75 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:24:07 +0100
Subject: [PATCH] kded: notify when networking is turned off for an offline
 vault

Opening a vault set to go offline switched networking off silently, so
people who forgot about the setting were left wondering why they had no
network. Now a notification says which vault turned networking off.

BUG: 501238
---
 CMakeLists.txt            |  1 +
 kded/CMakeLists.txt       |  2 ++
 kded/plasmavault.notifyrc |  9 +++++++++
 kded/service.cpp          | 14 ++++++++++++++
 4 files changed, 26 insertions(+)
 create mode 100644 kded/plasmavault.notifyrc

diff --git a/CMakeLists.txt b/CMakeLists.txt
index a840d4a..621787b 100644
--- a/CMakeLists.txt
+++ b/CMakeLists.txt
@@ -61,6 +61,7 @@ find_package(KF6 ${KF6_MIN_VERSION} REQUIRED COMPONENTS
     I18n
     ItemModels
     KIO
+    Notifications
     Service
 )

diff --git a/kded/CMakeLists.txt b/kded/CMakeLists.txt
index aa9c702..8c62c96 100644
--- a/kded/CMakeLists.txt
+++ b/kded/CMakeLists.txt
@@ -97,6 +97,7 @@ target_link_libraries(kded_plasmavault
     KF6::I18n
     KF6::KIOCore
     KF6::KIOWidgets
+    KF6::Notifications
     KF6::Service
     KSysGuard::ProcessCore
 )
@@ -107,3 +108,4 @@ if (HAVE_NETWORKMANAGER)
 endif()

 install(TARGETS kded_plasmavault DESTINATION ${KDE_INSTALL_PLUGINDIR}/kf6/kded)
+install(FILES plasmavault.notifyrc DESTINATION ${KDE_INSTALL_KNOTIFYRCDIR})
diff --git a/kded/plasmavault.notifyrc b/kded/plasmavault.notifyrc
new file mode 100644
index 0000000..6495c4b
--- /dev/null
+++ b/kded/plasmavault.notifyrc
@@ -0,0 +1,9 @@
+[Global]
+IconName=plasmavault
+Name=Plasma Vault
+Comment=Plasma Vault
+
+[Event/networkingDisabled]
+Name=Networking disabled
+Comment=Networking was turned off because a vault that has to be used offline was opened
+Action=Popup
diff --git a/kded/service.cpp b/kded/service.cpp
index ea44606..89f2701 100644
--- a/kded/service.cpp
+++ b/kded/service.cpp
@@ -9,6 +9,7 @@
 #include <QDBusObjectPath>
 #include <QFile>
 #include <QMessageBox>
+#include <QPointer>
 #include <QProcess>
 #include <QSocketNotifier>

@@ -16,6 +17,7 @@
 #include <KConfigGroup>
 #include <KIO/ApplicationLauncherJob>
 #include <KLocalizedString>
+#include <KNotification>
 #include <KPasswordDialog>
 #include <KPluginFactory>
 #include <KService>
@@ -76,6 +78,7 @@ public:
     };
     // Ideally, this would be std::optional... lovely C++17
     Expected<NetworkingState, int> savedNetworkingState = Expected<NetworkingState, int>::error(0);
+    QHash<Device, QPointer<KNotification>> networkingNotifications;

     void saveNetworkingState()
     {
@@ -277,10 +280,21 @@ void PlasmaVaultService::onVaultStatusChanged(VaultInfo::Status status)
             auto deviceOpeningHandle = "{opening}" + vault->device().data();
             devicesInhibittingNetworking.removeAll(deviceOpeningHandle);
             devicesInhibittingNetworking << vault->device().data();
+
+            auto notification = new KNotification(QStringLiteral("networkingDisabled"));
+            notification->setComponentName(QStringLiteral("plasmavault"));
+            notification->setTitle(i18n("Networking disabled"));
+            notification->setText(i18n("Networking has been turned off while the vault “%1” is open.", vault->name()));
+            notification->sendEvent();
+            d->networkingNotifications[vault->device()] = notification;
         }

         if (status != VaultInfo::Opened && alreadyInhibiting) {
             devicesInhibittingNetworking.removeAll(vault->device().data());
+
+            if (auto notification = d->networkingNotifications.take(vault->device())) {
+                notification->close();
+            }
         }

         // Now, let's handle the networking part
-- 
